using MovieInfoBackend.DataModels;
using Xunit.Abstractions;

public class TmdbPersonDataModelTests
{
    private string tmdbHttpClientPersonImagesResponse;
    private string tmdbHttpClientPersonMovieCreditsResponse;
    private string tmdbHttpClientPersonResponse;
    private string tmdbHttpClientPersonTvSeriesCreditsResponse;

    public TmdbPersonDataModelTests(ITestOutputHelper output)
    {
        // Arrange

        string testPersonImagesDataFilename = "TmdbHttpClientPersonImagesResponse.json";
        string testPersonMovieCreditsDataFilename = "TmdbHttpClientPersonMovieCreditsResponse.json";
        string testPersonDataFilename = "TmdbHttpClientPersonResponse.json";
        string testPersonTvSeriesCreditsDataFilename = "TmdbHttpClientPersonTvSeriesCreditsResponse.json";
        // Next file is unused currently
        //string testPersonCombinedCreditsDataFilename = "TmdbHttpClientPersonCombinedCreditsResponse.json";

        using (StreamReader sr = File.OpenText($"../../../TestData/{testPersonImagesDataFilename}"))
        {
            tmdbHttpClientPersonImagesResponse = sr.ReadToEnd();
        }
        if (String.IsNullOrWhiteSpace(tmdbHttpClientPersonImagesResponse))
        {
            throw new ArgumentException($"{testPersonImagesDataFilename} is not valid test data.");
        }

        using (StreamReader sr = File.OpenText($"../../../TestData/{testPersonMovieCreditsDataFilename}"))
        {
            tmdbHttpClientPersonMovieCreditsResponse = sr.ReadToEnd();
        }
        if (String.IsNullOrWhiteSpace(tmdbHttpClientPersonMovieCreditsResponse))
        {
            throw new ArgumentException($"{testPersonMovieCreditsDataFilename} is not valid test data.");
        }

        using (StreamReader sr = File.OpenText($"../../../TestData/{testPersonDataFilename}"))
        {
            tmdbHttpClientPersonResponse = sr.ReadToEnd();
        }
        if (String.IsNullOrWhiteSpace(tmdbHttpClientPersonResponse))
        {
            throw new ArgumentException($"{testPersonDataFilename} is not valid test data.");
        }

        using (StreamReader sr = File.OpenText($"../../../TestData/{testPersonTvSeriesCreditsDataFilename}"))
        {
            tmdbHttpClientPersonTvSeriesCreditsResponse = sr.ReadToEnd();
        }
        if (String.IsNullOrWhiteSpace(tmdbHttpClientPersonTvSeriesCreditsResponse))
        {
            throw new ArgumentException($"{testPersonTvSeriesCreditsDataFilename} is not valid test data.");
        }
    }

    [Fact]
    public void GetModelFromResponse_ValidResponse_ReturnsValidModels()
    {
        // Act
        
        TmdbPersonImagesResponseDataModel? personImagesResponse = TmdbHttpClient.GetPersonImagesModelFromResponse(tmdbHttpClientPersonImagesResponse);
        TmdbPersonMovieCreditsResponseDataModel? personMovieCreditsResponse = TmdbHttpClient.GetPersonMovieCreditsModelFromResponse(tmdbHttpClientPersonMovieCreditsResponse);
        TmdbPersonResponseDataModel? personResponse = TmdbHttpClient.GetPersonModelFromResponse(tmdbHttpClientPersonResponse);
        TmdbPersonTvSeriesCreditsResponseDataModel? personTvSeriesCreditsResponse = TmdbHttpClient.GetPersonTvSeriesCreditsModelFromResponse(tmdbHttpClientPersonTvSeriesCreditsResponse);

        // Assert

        // Person images
        Assert.NotNull(personImagesResponse);
        Assert.NotEmpty(personImagesResponse.Profiles);
        TmdbProfileDataModel firstProfile = personImagesResponse.Profiles[0];
        Assert.True(firstProfile.AspectRatio > 0.0, "Image profile AspectRatio must be a positive decimal number");
        Assert.True(firstProfile.Height > 0, "Image profile Height must be a positive number");
        Assert.False(String.IsNullOrWhiteSpace(firstProfile.FilePath), "Image profile FilePath must not be empty");
        Assert.True(firstProfile.VoteAverage >= 0.0, "Image profile VoteAverage must not be a negative decimal number");
        Assert.True(firstProfile.VoteCount >= 0, "Image profile VoteCount must not be a negative number");
        Assert.True(firstProfile.Width > 0, "Image profile Width must be a positive number");

        // Person movie credits
        Assert.NotNull(personMovieCreditsResponse);
        Assert.NotEmpty(personMovieCreditsResponse.Cast);
        TmdbPersonMovieCastDataModel firstMovieCast = personMovieCreditsResponse.Cast[0];
        Assert.False(String.IsNullOrWhiteSpace(firstMovieCast.BackdropPath), "Person movie cast BackdropPath must not be empty");
        Assert.NotEmpty(firstMovieCast.GenreIds);
        Assert.True(firstMovieCast.Id > 0, "Person movie cast Id must be a positive number");
        Assert.False(String.IsNullOrWhiteSpace(firstMovieCast.Title), "Person movie cast Title must not be empty");
        Assert.False(String.IsNullOrWhiteSpace(firstMovieCast.OriginalLanguage), "Person movie cast OriginalLanguage must not be empty");
        Assert.False(String.IsNullOrWhiteSpace(firstMovieCast.OriginalTitle), "Person movie cast OriginalTitle must not be empty");
        Assert.False(String.IsNullOrWhiteSpace(firstMovieCast.Overview), "Person movie cast Overview must not be empty");
        Assert.True(firstMovieCast.Popularity >= 0.0, "Person movie cast Popularity must not be a negative decimal number");
        Assert.False(String.IsNullOrWhiteSpace(firstMovieCast.PosterPath), "Person movie cast PosterPath must not be empty");
        Assert.False(String.IsNullOrWhiteSpace(firstMovieCast.ReleaseDate), "Person movie cast ReleaseDate must not be empty");
        Assert.True(firstMovieCast.VoteAverage >= 0.0, "Person movie cast VoteAverage must not be a negative decimal number");
        Assert.True(firstMovieCast.VoteCount >= 0, "Person movie cast VoteCount must not be a negative number");
        Assert.False(String.IsNullOrWhiteSpace(firstMovieCast.Character), "Person movie cast Character must not be empty");
        Assert.False(String.IsNullOrWhiteSpace(firstMovieCast.CreditId), "Person movie cast CreditId must not be empty");
        Assert.True(firstMovieCast.Order >= 0, "Person movie cast Order must not be a negative number");
        Assert.NotEmpty(personMovieCreditsResponse.Crew);
        TmdbPersonMovieCrewDataModel firstMovieCrew = personMovieCreditsResponse.Crew[0];
        Assert.False(String.IsNullOrWhiteSpace(firstMovieCrew.BackdropPath), "Person movie crew BackdropPath must not be empty");
        Assert.NotEmpty(firstMovieCrew.GenreIds);
        Assert.True(firstMovieCrew.Id > 0, "Person movie crew Id must be a positive number");
        Assert.False(String.IsNullOrWhiteSpace(firstMovieCrew.Title), "Person movie crew Title must not be empty");
        Assert.False(String.IsNullOrWhiteSpace(firstMovieCrew.OriginalLanguage), "Person movie crew OriginalLanguage must not be empty");
        Assert.False(String.IsNullOrWhiteSpace(firstMovieCrew.OriginalTitle), "Person movie crew OriginalTitle must not be empty");
        Assert.False(String.IsNullOrWhiteSpace(firstMovieCrew.Overview), "Person movie crew Overview must not be empty");
        Assert.True(firstMovieCrew.Popularity >= 0.0, "Person movie crew Popularity must not be a negative decimal number");
        Assert.False(String.IsNullOrWhiteSpace(firstMovieCrew.PosterPath), "Person movie crew PosterPath must not be empty");
        Assert.False(String.IsNullOrWhiteSpace(firstMovieCrew.ReleaseDate), "Person movie crew ReleaseDate must not be empty");
        Assert.True(firstMovieCrew.VoteAverage >= 0.0, "Person movie crew VoteAverage must not be a negative decimal number");
        Assert.True(firstMovieCrew.VoteCount >= 0, "Person movie crew VoteCount must not be a negative number");
        Assert.False(String.IsNullOrWhiteSpace(firstMovieCrew.CreditId), "Person movie crew CreditId must not be empty");
        Assert.False(String.IsNullOrWhiteSpace(firstMovieCrew.Department), "Person movie crew Character must not be empty");
        Assert.False(String.IsNullOrWhiteSpace(firstMovieCrew.Job), "Person movie crew Job must not be empty");

        // Person
        Assert.NotNull(personResponse);
        Assert.NotNull(personResponse.AlsoKnownAs);
        Assert.False(String.IsNullOrWhiteSpace(personResponse.Birthday), "Person Birthday must not be empty");
        Assert.True(personResponse.Gender >= 0, "Person Gender must not be a negative number");
        Assert.True(personResponse.TmdbId > 0, "Person TmdbId must be a positive number");
        Assert.False(String.IsNullOrWhiteSpace(personResponse.ImdbId), "Person ImdbId must not be empty");
        Assert.False(String.IsNullOrWhiteSpace(personResponse.KnownForDepartment), "Person KnownForDepartment must not be empty");
        Assert.False(String.IsNullOrWhiteSpace(personResponse.Name), "Person Name must not be empty");
        Assert.False(String.IsNullOrWhiteSpace(personResponse.PlaceOfBirth), "Person PlaceOfBirth must not be empty");
        Assert.True(personResponse.Popularity >= 0.0, "Person Popularity must not be a negative decimal number");

        // Person TV series credits
        Assert.NotNull(personTvSeriesCreditsResponse);
        Assert.NotEmpty(personTvSeriesCreditsResponse.Cast);
        TmdbPersonTvSeriesCastDataModel firstTvSeriesCast = personTvSeriesCreditsResponse.Cast[0];
        Assert.False(String.IsNullOrWhiteSpace(firstTvSeriesCast.BackdropPath), "Person TV series cast BackdropPath must not be empty");
        Assert.NotEmpty(firstTvSeriesCast.GenreIds);
        Assert.True(firstTvSeriesCast.Id > 0, "Person TV series cast Id must be a positive number");
        Assert.NotEmpty(firstTvSeriesCast.OriginCountry);
        Assert.False(String.IsNullOrWhiteSpace(firstTvSeriesCast.OriginalLanguage), "Person TV series cast OriginalLanguage must not be empty");
        Assert.False(String.IsNullOrWhiteSpace(firstTvSeriesCast.OriginalName), "Person TV series cast OriginalName must not be empty");
        Assert.False(String.IsNullOrWhiteSpace(firstTvSeriesCast.Overview), "Person TV series cast Overview must not be empty");
        Assert.True(firstTvSeriesCast.Popularity >= 0.0, "Person TV series cast Popularity must not be a negative decimal number");
        Assert.False(String.IsNullOrWhiteSpace(firstTvSeriesCast.PosterPath), "Person TV series cast PosterPath must not be empty");
        Assert.False(String.IsNullOrWhiteSpace(firstTvSeriesCast.Name), "Person TV series cast Name must not be empty");
        Assert.True(firstTvSeriesCast.VoteAverage >= 0.0, "Person TV series cast VoteAverage must not be a negative decimal number");
        Assert.True(firstTvSeriesCast.VoteCount >= 0, "Person TV series cast VoteCount must not be a negative number");
        Assert.False(String.IsNullOrWhiteSpace(firstTvSeriesCast.Character), "Person TV series cast Character must not be empty");
        Assert.False(String.IsNullOrWhiteSpace(firstTvSeriesCast.CreditId), "Person TV series cast CreditId must not be empty");
        Assert.True(firstTvSeriesCast.EpisodeCount > 0, "Person TV series cast EpisodeCount must be a positive number");
        Assert.False(String.IsNullOrWhiteSpace(firstTvSeriesCast.FirstCreditAirDate), "Person TV series cast FirstCreditAirDate must not be empty");
        Assert.NotEmpty(personTvSeriesCreditsResponse.Crew);
        TmdbPersonTvSeriesCrewDataModel firstTvSeriesCrew = personTvSeriesCreditsResponse.Crew[0];
        Assert.False(String.IsNullOrWhiteSpace(firstTvSeriesCrew.BackdropPath), "Person TV series crew BackdropPath must not be empty");
        Assert.NotEmpty(firstTvSeriesCrew.GenreIds);
        Assert.True(firstTvSeriesCrew.Id > 0, "Person TV series crew Id must be a positive number");
        Assert.NotEmpty(firstTvSeriesCrew.OriginCountry);
        Assert.False(String.IsNullOrWhiteSpace(firstTvSeriesCrew.OriginalLanguage), "Person TV series crew OriginalLanguage must not be empty");
        Assert.False(String.IsNullOrWhiteSpace(firstTvSeriesCrew.OriginalName), "Person TV series crew OriginalName must not be empty");
        Assert.False(String.IsNullOrWhiteSpace(firstTvSeriesCrew.Overview), "Person TV series crew Overview must not be empty");
        Assert.True(firstTvSeriesCrew.Popularity >= 0.0, "Person TV series crew Popularity must not be a negative decimal number");
        Assert.False(String.IsNullOrWhiteSpace(firstTvSeriesCrew.PosterPath), "Person TV series crew PosterPath must not be empty");
        Assert.False(String.IsNullOrWhiteSpace(firstTvSeriesCrew.Name), "Person TV series crew Name must not be empty");
        Assert.True(firstTvSeriesCrew.VoteAverage >= 0.0, "Person TV series crew VoteAverage must not be a negative decimal number");
        Assert.True(firstTvSeriesCrew.VoteCount >= 0, "Person TV series crew VoteCount must not be a negative number");
        Assert.False(String.IsNullOrWhiteSpace(firstTvSeriesCrew.CreditId), "Person TV series crew CreditId must not be empty");
        Assert.False(String.IsNullOrWhiteSpace(firstTvSeriesCrew.Department), "Person TV series crew Department must not be empty");
        Assert.True(firstTvSeriesCrew.EpisodeCount > 0, "Person TV series crew EpisodeCount must be a positive number");
        Assert.False(String.IsNullOrWhiteSpace(firstTvSeriesCrew.FirstCreditAirDate), "Person TV series crew FirstCreditAirDate must not be empty");
        Assert.False(String.IsNullOrWhiteSpace(firstTvSeriesCrew.Job), "Person TV series crew Job must not be empty");
    }

